"""Randomized differential test: a long-lived refreshed resolver must always
agree, field by field, with a resolver built fresh from the *currently
exposed* table. Failures (None/bad table) must be ImproperlyConfigured on
both sides, path misses Resolver404 on both sides."""
import random
import types

import django
from django.conf import settings

settings.configure(DEBUG=True, ROOT_URLCONF="x", USE_TZ=True)
django.setup()

from django.core.exceptions import ImproperlyConfigured
from django.urls import Resolver404, include, path, resolve
from django.urls.converters import register_converter

random.seed(20260929)


def v_a(request, **k):
    pass


def v_b(request, **k):
    pass


def v_c(request, **k):
    pass


VIEWS = [v_a, v_b, v_c]


class Typed:
    def __init__(self, v):
        self.v = v

    def __eq__(self, o):
        return isinstance(o, Typed) and o.v == o.v and self.v == o.v

    def __repr__(self):
        return f"Typed({self.v!r})"


class TypedConverter:
    regex = r"[\w%/:@ .\-]+"

    def to_python(self, v):
        if v == "bad":
            raise ValueError
        return Typed(v)

    def to_url(self, v):
        return getattr(v, "v", str(v))


register_converter(TypedConverter, "rtyp")


class Conf:
    def __init__(self, p, app_name=None):
        self.urlpatterns = p
        if app_name:
            self.app_name = app_name


PARAMS = [
    ("<int:n>", "int", ["1", "42", "%34%32"], ["x", "1/2", "", "bad"]),
    ("<slug:s>", "slug", ["abc", "a-b_c"], ["a b", "a/b", "", "a%20b"]),
    ("<rtyp:t>", "rtyp", [
        "hello", "caf%C3%A9", "a%2Fb", "a%252Fb", "x%20y", "p%3Aq",
    ], ["", "bad"]),
